// Paramètres de la carte de distance fractale
#define VITESSE_ROTATION_FRACTALE 0.1
#define SEUIL_DISTANCE_MAX 100000.0
#define ITERATIONS_FRACTALE 7
#define FACTEUR_ECHELLE_PLIAGE 0.6
#define DECALAGE_PLIAGE 0.5
#define FACTEUR_MULT_PLIAGE 2.0
#define NUMERATEUR_INVERSION 1.2
#define CLAMP_INVERSION_MIN 0.27
#define CLAMP_INVERSION_MAX 1.0
#define FACTEUR_ESTIMATION_SURFACE 0.11
#define MODULO_MATERIAU 5.0

// Paramètres des ombres adoucies
#define DECALAGE_OMBRE_INITIAL 0.01
#define ITERATIONS_OMBRE 30
#define SEUIL_INTERSECTION_OMBRE 0.001
#define INTENSITE_OMBRE_MAX 16.0
#define PAS_OMBRE_MIN 0.002
#define PAS_OMBRE_MAX 0.1
#define DISTANCE_MAX_OMBRE 3.0
#define BIAS_NORMALE_OMBRE 0.002

// Paramètres de la normale
#define EPSILON_NORMALE 0.0005

// Paramètres de la caméra
#define VITESSE_ORBITE_CAMERA 0.2
#define RAYON_ORBITE_CAMERA 0.7
#define HAUTEUR_CAMERA 0.67
#define FACTEUR_OUVERTURE_CAMERA 1.5

// Paramètres du Raymarching principal
#define COULEUR_FOND vec3(0.02, 0.03, 0.05)
#define ITERATIONS_RAYMARCHING 150
#define SEUIL_INTERSECTION 0.001
#define DISTANCE_MAX_RAYMARCHING 20.0
#define FACTEUR_GLOW_LUMIERE 40.0
#define FACTEUR_GLOW_FOND 0.0004

// Paramètres d'éclairage et ombrage
#define AMBIANT_BASE vec3(0.08)
#define PUISSANCE_SPECULAIRE 32.0
#define MULT_DIFFUSE_LUMIERE_SURENT 1.3
#define MULT_SPEC_LUMIERE_0 0.2
#define MULT_SPEC_LUMIERE_1 0.3
#define MULT_SPEC_LUMIERE_AUTRES 0.4

// Positions des 5 lumières
#define POS_LUMIERE_0 vec3(0.5, 1.5, -1.0)
#define VITESSE_LUMIERE_1 -0.6
#define RAYON_LUMIERE_1 1.5
#define HAUTEUR_LUMIERE_1 0.8
#define VITESSE_LUMIERE_2 1.2
#define MULT_LUMIERE_2_3 1.5
#define HAUTEUR_LUMIERE_2_3 0.5
#define VITESSE_LUMIERE_4 0.8
#define RAYON_LUMIERE_4 0.8
#define HAUTEUR_LUMIERE_4 1.8

// Couleurs des 5 lumières
#define COULEUR_LUMIERE_0 vec3(0.3)
#define COULEUR_LUMIERE_1 vec3(0.3, 0.5, 0.7)
#define COULEUR_LUMIERE_2 vec3(1.0, 0.15, 0.1)
#define COULEUR_LUMIERE_3 vec3(0.1, 0.3, 1.0)
#define COULEUR_LUMIERE_4 vec3(0.15, 0.9, 0.2)

// Matériaux / Albédos
#define MAT_ROUGE vec3(0.95, 0.2, 0.2)
#define MAT_JAUNE vec3(0.95, 0.75, 0.1)
#define MAT_VERT  vec3(0.15, 0.85, 0.35)
#define MAT_BLEU  vec3(0.1, 0.7, 0.95)
#define MAT_VIOLET vec3(0.65, 0.25, 0.9)

// Rendu final et post-traitement
#define COEFF_ATTENUATION_BROUILLARD -0.25
#define EXPOSANT_CORRECTION_GAMMA 0.4545
#define VALEUR_ALPHA 1.0

vec2 calculerCarteDistanceFractale(vec3 position) {
    float angleRotation = iTime * VITESSE_ROTATION_FRACTALE;
    float facteurEchelleGlobal = 1.0;
    float distanceMinimale = SEUIL_DISTANCE_MAX;
    float distanceCourante;
    float facteurInversionSpherique;
    float indexIterationProche = 0.0;

    mat2 matriceRotationXZ = mat2(
        cos(angleRotation), sin(angleRotation),
        -sin(angleRotation), cos(angleRotation)
    );

    position.xz *= matriceRotationXZ;

    for (int it = 0; it < ITERATIONS_FRACTALE; it++) {
        position = fract(position * FACTEUR_ECHELLE_PLIAGE + DECALAGE_PLIAGE) * FACTEUR_MULT_PLIAGE - 1.0;

        float produitScalaire = dot(position, position);
        facteurInversionSpherique = NUMERATEUR_INVERSION / clamp(produitScalaire, CLAMP_INVERSION_MIN, CLAMP_INVERSION_MAX);

        position *= facteurInversionSpherique;
        facteurEchelleGlobal *= facteurInversionSpherique;

        distanceCourante = length(position) / facteurEchelleGlobal;
        if (distanceCourante < distanceMinimale) {
            distanceMinimale = distanceCourante;
            indexIterationProche = float(it);
        }
    }

    float distanceEstimationSurface = FACTEUR_ESTIMATION_SURFACE * abs(position.y) / facteurEchelleGlobal;
    float identifiantMateriau = mod(indexIterationProche, MODULO_MATERIAU);

    return vec2(distanceEstimationSurface, identifiantMateriau);
}

float calculerOmbreAdoucie(vec3 origineRayon, vec3 directionLumiere) {
    float intensiteOmbre = 1.0;
    float distanceParcourue = DECALAGE_OMBRE_INITIAL;
    float distanceEstimation;

    for (int i = 0; i < ITERATIONS_OMBRE; i++) {
        distanceEstimation = calculerCarteDistanceFractale(origineRayon + directionLumiere * distanceParcourue).x;
        if (distanceEstimation < SEUIL_INTERSECTION_OMBRE) {
            return 0.0;
        }
        intensiteOmbre = min(intensiteOmbre, INTENSITE_OMBRE_MAX * distanceEstimation / distanceParcourue);
        distanceParcourue += clamp(distanceEstimation, PAS_OMBRE_MIN, PAS_OMBRE_MAX);
        if (distanceParcourue > DISTANCE_MAX_OMBRE) {
            break;
        }
    }

    return clamp(intensiteOmbre, 0.0, 1.0);
}

vec3 calculerNormale(vec3 position) {
    vec2 decalage = vec2(EPSILON_NORMALE, 0.0);
    return normalize(vec3(
        calculerCarteDistanceFractale(position + decalage.xyy).x - calculerCarteDistanceFractale(position - decalage.xyy).x,
        calculerCarteDistanceFractale(position + decalage.yxy).x - calculerCarteDistanceFractale(position - decalage.yxy).x,
        calculerCarteDistanceFractale(position + decalage.yyx).x - calculerCarteDistanceFractale(position - decalage.yyx).x
    ));
}

void mainImage(out vec4 couleurFragment, vec2 coordFragment) {
    vec2 uvNormalisees = (coordFragment.xy - 0.5 * iResolution.xy) / iResolution.y;

    vec3 positionCamera = vec3(
        sin(iTime * VITESSE_ORBITE_CAMERA) * RAYON_ORBITE_CAMERA,
        HAUTEUR_CAMERA,
        cos(iTime * VITESSE_ORBITE_CAMERA) * RAYON_ORBITE_CAMERA
    );

    vec3 directionArriere = normalize(-positionCamera);
    vec3 directionDroite = normalize(cross(directionArriere, vec3(0.0, 1.0, 0.0)));
    vec3 directionHaut = cross(directionDroite, directionArriere);

    vec3 directionRayon = normalize(
        uvNormalisees.x * directionDroite +
        uvNormalisees.y * directionHaut +
        FACTEUR_OUVERTURE_CAMERA * directionArriere
    );

    vec3 couleurAccumulee = COULEUR_FOND;
    vec3 positionIntersection;

    float distanceParcourueTotal = 0.0;
    float intensiteGlowVolumetrique = 0.0;
    float etapeMarchage = 0.0;
    float distanceEstimation = 0.0;
    vec2 resultatCarteDistance;

    for (int i = 0; i < ITERATIONS_RAYMARCHING; i++) {
        etapeMarchage += 1.0;
        resultatCarteDistance = calculerCarteDistanceFractale(positionCamera + directionRayon * distanceParcourueTotal);
        distanceEstimation = resultatCarteDistance.x;

        if (distanceEstimation < SEUIL_INTERSECTION || distanceParcourueTotal > DISTANCE_MAX_RAYMARCHING) {
            break;
        }

        distanceParcourueTotal += distanceEstimation;
        intensiteGlowVolumetrique += 1.0 / (1.0 + distanceEstimation * FACTEUR_GLOW_LUMIERE);
    }

    if (distanceEstimation < SEUIL_INTERSECTION) {
        positionIntersection = positionCamera + directionRayon * distanceParcourueTotal;
        vec3 normaleSurface = calculerNormale(positionIntersection);

        vec3 positionsLumieres[5];
        positionsLumieres[0] = POS_LUMIERE_0;
        positionsLumieres[1] = vec3(cos(iTime * VITESSE_LUMIERE_1) * RAYON_LUMIERE_1, HAUTEUR_LUMIERE_1, sin(iTime * VITESSE_LUMIERE_1) * RAYON_LUMIERE_1);
        positionsLumieres[2] = vec3(0.0, sin(iTime * VITESSE_LUMIERE_2) * MULT_LUMIERE_2_3, HAUTEUR_LUMIERE_2_3);
        positionsLumieres[3] = vec3(0.0, -sin(iTime * VITESSE_LUMIERE_2) * MULT_LUMIERE_2_3, -HAUTEUR_LUMIERE_2_3);
        positionsLumieres[4] = vec3(cos(iTime * VITESSE_LUMIERE_4) * RAYON_LUMIERE_4, HAUTEUR_LUMIERE_4, sin(iTime * VITESSE_LUMIERE_4) * RAYON_LUMIERE_4);

        vec3 couleursLumieres[5];
        couleursLumieres[0] = COULEUR_LUMIERE_0;
        couleursLumieres[1] = COULEUR_LUMIERE_1;
        couleursLumieres[2] = COULEUR_LUMIERE_2;
        couleursLumieres[3] = COULEUR_LUMIERE_3;
        couleursLumieres[4] = COULEUR_LUMIERE_4;

        vec3 couleurDiffuseAccumulee = AMBIANT_BASE;
        vec3 couleurSpeculaireAccumulee = vec3(0.0);
        vec3 directionLumiere;

        for (int j = 0; j < 5; j++) {
            vec3 origineSource = (j == 0) ? vec3(0.0) : positionIntersection;
            directionLumiere = normalize(positionsLumieres[j] - origineSource);

            float facteurOmbre = calculerOmbreAdoucie(positionIntersection + normaleSurface * BIAS_NORMALE_OMBRE, directionLumiere);

            float intensiteDiffuse = max(dot(normaleSurface, directionLumiere), 0.0);
            float multiplicateurDiffuse = (j > 1) ? MULT_DIFFUSE_LUMIERE_SURENT : 1.0;
            couleurDiffuseAccumulee += couleursLumieres[j] * intensiteDiffuse * facteurOmbre * multiplicateurDiffuse;

            vec3 demiVecteur = normalize(directionLumiere - directionRayon);
            float intensiteSpeculaire = pow(max(dot(normaleSurface, demiVecteur), 0.0), PUISSANCE_SPECULAIRE);
            float multiplicateurSpeculaire = (j == 0) ? MULT_SPEC_LUMIERE_0 : (j == 1) ? MULT_SPEC_LUMIERE_1 : MULT_SPEC_LUMIERE_AUTRES;
            couleurSpeculaireAccumulee += couleursLumieres[j] * intensiteSpeculaire * facteurOmbre * multiplicateurSpeculaire;
        }

        float idMateriau = resultatCarteDistance.y;
        vec3 couleurAlbedoBase = (idMateriau < 1.0) ? MAT_ROUGE :
                                 (idMateriau < 2.0) ? MAT_JAUNE :
                                 (idMateriau < 3.0) ? MAT_VERT :
                                 (idMateriau < 4.0) ? MAT_BLEU :
                                                      MAT_VIOLET;

        vec3 couleurEclairageComplet = couleurAlbedoBase * couleurDiffuseAccumulee + couleurSpeculaireAccumulee;
        float facteurBrouillard = exp(COEFF_ATTENUATION_BROUILLARD * distanceParcourueTotal);

        couleurAccumulee = mix(couleurAccumulee, couleurEclairageComplet, facteurBrouillard);
    } else {
        couleurAccumulee += FACTEUR_GLOW_FOND * intensiteGlowVolumetrique;
    }

    vec3 couleurAjustementGamma = pow(couleurAccumulee, vec3(EXPOSANT_CORRECTION_GAMMA));
    couleurFragment = vec4(couleurAjustementGamma, VALEUR_ALPHA);
}
